(()=>{window.IndianWatch={mount(host){let active=true,busy=false,dirty=false;host.innerHTML='<section class="india-step-card"><h3>Saved strategy watchlist</h3><p>Checks up to eight NSE symbols using your saved Dhan connection. Your local terminal must stay running; the browser may be closed. Each saved symbol is due every minute. Checks run sequentially; slow providers can delay a full pass. This is separate from the full NSE scanner.</p><label><input data-iw-enabled type="checkbox"> Enable saved strategy checks</label><label>Exact NSE symbols, comma-separated<input data-iw-symbols placeholder="NSE:TCS-EQ, NSE:RELIANCE-EQ"></label><button data-iw-save>Save watchlist</button><button data-iw-step>Check next due stock</button><button data-iw-refresh>Refresh saved results</button><p data-iw-status role="status"></p><div data-iw-results></div><p>Only confirmed results with fresh quotes create saved title-only alerts here. No Indian WhatsApp delivery or order placement is added by this watchlist.</p></section>';const q=n=>host.querySelector('[data-iw-'+n+']'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(path,body){const r=await fetch('/api/indian-watch'+path,{method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(65000)});const d=await r.json();if(!r.ok||d.error)throw Error(d.error||'Saved check unavailable');return d}async function load(){const d=await api('');if(!active)return;const s=d.settings;if(!dirty){q('enabled').checked=s.enabled;q('symbols').value=s.symbols.join(', ')};q('status').textContent=d.runner+' · '+(s.enabled?'Enabled':'Paused');q('results').innerHTML=Object.values(s.results).map(r=>'<p><strong>'+esc(r.symbol)+'</strong> · '+esc(new Date(r.checkedAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))+' IST · '+esc(r.error||r.errors?.join(' · ')||(r.results||[]).map(x=>x.strategy+': '+x.status).join(' · '))+'</p>').join('')+(s.alerts||[]).map(a=>'<p><strong>'+esc(a.title)+'</strong></p>').join('')}async function act(task){if(busy)return;busy=true;for(const n of ['save','step','refresh','enabled','symbols'])q(n).disabled=true;try{await task()}catch(e){if(active)q('status').textContent=e.message}finally{busy=false;if(active)for(const n of ['save','step','refresh','enabled','symbols'])q(n).disabled=false}}q('symbols').oninput=q('enabled').onchange=()=>{dirty=true};q('save').onclick=()=>act(async()=>{await api('',{enabled:q('enabled').checked,symbols:q('symbols').value.split(',').map(x=>x.trim().toUpperCase()).filter(Boolean)});dirty=false;await load()});q('step').onclick=()=>act(async()=>{if(dirty)throw Error('Save your watchlist changes before checking.');const d=await api('/step',{});await load();if(active&&d.reason)q('status').textContent=d.reason});q('refresh').onclick=()=>act(load);act(load);return()=>{active=false}}};})();
